// src/features/tasks/components/status-pill.tsx: Reanimated's docs shape, a config bound to a const.
import { withSpring } from 'react-native-reanimated';

import type { WithSpringConfig } from 'react-native-reanimated';

const BOUNCE = { damping: 10, stiffness: 100 } as const;
const SOFT = { mass: 2 } satisfies WithSpringConfig;

export const settle = () => withSpring(1, BOUNCE);
export const release = (velocity: number) => withSpring(0, { ...SOFT, velocity });

// src/features/tasks/components/fade-row.tsx: timing configs bound to consts, as Reanimated's docs write them.
import { withDelay, withTiming } from 'react-native-reanimated';

const FADE = { duration: 250 };
const STAGGER_MS = 120;
const SESSION = { duration: 25 };

export const fadeIn = () => withTiming(1, FADE);
export const later = () => withDelay(STAGGER_MS, withTiming(1, FADE));
export const minutes = () => SESSION.duration;

// src/core/tasks/estimate.ts: a pure domain value (never scanned: src/core draws nothing).
export const DEFAULT_ESTIMATE = { duration: 25, unit: 'min' } as const;
export const withTiming = (minutes: number) => ({ duration: minutes * 60 });

// src/features/tasks/use-focus-session-model.ts: a duration that is data, not an animation.
import { withSpring } from 'react-native-reanimated';

import { SPRINGS } from '@/theme/motion';

export const SESSION = { duration: 25, breakMinutes: 5 };
export const settle = (velocity: number) => withSpring(0, { ...SPRINGS.release, velocity });
export const later = (dayjs: { duration: (n: number, unit: string) => unknown }) => dayjs.duration(25, 'minutes');

// src/features/tasks/components/hero-banner.tsx: gradients are allowed unless the policy bans them.
import { LinearGradient } from 'expo-linear-gradient';

export const Banner = LinearGradient;

// src/app/+html.tsx: the static web root paints both schemes' ground at export time.
import { PALETTE } from '@/theme/palette';

export const GROUND_CSS = `body { background: ${PALETTE.light.background}; } @media (prefers-color-scheme: dark) { body { background: ${PALETTE.dark.background}; } }`;

// src/features/tasks/components/task-badge.tsx
import { Switch, View } from 'react-native';

import { useTheme } from '@/theme/use-theme';
import { AppText } from '@/ui/app-text';

type Swatch = { readonly color: 'red' | 'blue' };

export function TaskBadge({ swatch }: { readonly swatch: Swatch }) {
  const theme = useTheme();
  return (
    <View accessibilityHint="red">
      <AppText variant="label" tone="danger">
        {swatch.color}
      </AppText>
      <Switch
        thumbColor={theme.colors.surface}
        trackColor={{ false: 'transparent', true: theme.colors.primary }}
        accessibilityLabel="green"
      />
    </View>
  );
}

